export async function processOutreach() {
  console.log("=================================================");
  console.log("🚀 ALPAR AI Enterprise Outreach Engine v1.0");
  console.log(`From Address: ${SENDER}`);
  console.log(
    `Execution Mode: ${EXECUTE_SEND ? "LIVE (REAL SEND)" : "🔒 DRY-RUN (SAFETY SHIELD ENABLED)"}`,
  );
  console.log("=================================================\n");

  if (!(vault.read('RESEND_API_KEY') ?? process.env.RESEND_API_KEY) && EXECUTE_SEND) {
    console.error("❌ ERROR: RESEND_API_KEY environment variable is missing!");
    process.exit(1);
  }

  const resend = new Resend((vault.read('RESEND_API_KEY') ?? process.env.RESEND_API_KEY) || "re_dummy_key_for_dry_run");

  const results: {
    id: string;
    company: string;
    recipient: string;
    status: "DRY_RUN" | "SENT" | "FAILED";
    resendId?: string;
    error?: string;
  }[] = [];

  for (let i = 0; i < ENTERPRISE_TARGETS.length; i++) {
    const target = ENTERPRISE_TARGETS[i];
    if (!target) continue;

    const htmlContent = buildEnterpriseEmailHtml(target);
    const textContent = buildEnterpriseEmailText(target);

    console.log(
      `[${i + 1}/${ENTERPRISE_TARGETS.length}] Processing ${target.id} - ${target.companyName} (${target.targetRole})`,
    );
    console.log(`   To: ${target.recipientEmail}`);
    console.log(`   Subject: ${target.subject}`);

    if (!EXECUTE_SEND) {
      console.log(
        `   🔒 DRY-RUN MODE: Email preview generated (${htmlContent.length} bytes HTML). Not dispatched.`,
      );
      results.push({
        id: target.id,
        company: target.companyName,
        recipient: target.recipientEmail,
        status: "DRY_RUN",
      });
    } else {
      try {
        console.log("   📡 Dispatching via Resend API...");
        const data = await resend.emails.send({
          from: SENDER,
          to: target.recipientEmail,
          subject: target.subject,
          html: htmlContent,
          text: textContent,
        });

        if (data.error) {
          console.error(`   ❌ Resend Error: ${JSON.stringify(data.error)}`);
          results.push({
            id: target.id,
            company: target.companyName,
            recipient: target.recipientEmail,
            status: "FAILED",
            error: JSON.stringify(data.error),
          });
        } else {
          console.log(`   ✅ Sent! Resend ID: ${data.data?.id}`);
          results.push({
            id: target.id,
            company: target.companyName,
            recipient: target.recipientEmail,
            status: "SENT",
            resendId: data.data?.id,
          });
        }
      } catch (err) {
        const errorMsg = err instanceof Error ? err.message : String(err);
        console.error(`   ❌ Exception: ${errorMsg}`);
        results.push({
          id: target.id,
          company: target.companyName,
          recipient: target.recipientEmail,
          status: "FAILED",
          error: errorMsg,
        });
      }

      // Rate limit safety: 500ms delay between API requests
      await new Promise((resolve) => setTimeout(resolve, 500));
    }
  }

  console.log("\n=================================================");
  console.log("📊 OUTREACH EXECUTION SUMMARY");
  console.log("=================================================");
  console.table(results);

  if (!EXECUTE_SEND) {
    console.log(
      "\n💡 Note: No emails were sent to actual targets because EXECUTE_SEND is not set to 'true'.",
    );
    console.log(
      "To execute live sending, run: EXECUTE_SEND=true npx tsx scripts/outreach/send-enterprise-emails.ts",
    );
  }
}

// Automatically execute if invoked directly
if (
  require.main === module ||
  (typeof process !== "undefined" && process.argv[1]?.includes("send-enterprise-emails"))
) {
  processOutreach().catch((err) => {
    console.error("Fatal error during outreach execution:", err);
    process.exit(1);
  });
}
